// Готує один рядок для Google-таблиці.
// Ключі мають збігатися із заголовками в першому рядку аркуша.
const out = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const v = (x) => (x === undefined || x === null) ? '' : String(x);

  const row = {
    'lead_id':          v(b.lead_id),
    'Оновлено':         new Date().toISOString(),
    'Статус':           b.stage === 'registration' ? 'Реєстрація завершена' : 'Тільки контакти',
    'Курс':             v(b.course_name),
    'Місто':            v(b.course_city),
    'Дата курсу':       v(b.course_date),
    "Ім'я":             v(b.name),
    'Телефон':          v(b.phone),
    'Email':            v(b.email),
    'ПІБ українською':  v(b.fullnameUa),
    'ПІБ англійською':  v(b.fullnameEn),
    'Дата народження':  v(b.dob),
    'Статус учасника':  v(b.status),
    'Бали БПР':         v(b.bpr),
    'Освіта':           v(b.education),
    'Спеціальність':    v(b.specialty),
    'Місце роботи':     v(b.workplace),
    'Посада':           v(b.position),
    'Учасники групи':   v(b.groupList),
    'Коментар':         v(b.comment),
    'Viber-група':      v(b.viber_group),
    'utm_source':       v(b.utm_source),
    'utm_medium':       v(b.utm_medium),
    'utm_campaign':     v(b.utm_campaign),
    'utm_content':      v(b.utm_content),
    'utm_term':         v(b.utm_term),
    'Сторінка':         v(b.page_url)
  };

  // «Створено» пишемо лише на першому кроці, щоб не затирати його на другому
  if (b.stage !== 'registration') {
    row['Створено'] = new Date().toISOString();
  }

  out.push({ json: row });
}

return out;
